/* ============================================================
   أطياب الجاسم (React) — صفحات القوائم (عطور · بخور · عود)

   ★ مصدر البيانات الوحيد: Redux — كل صفحة تستدعي thunk شريحتها
     عند التركيب (condition يمنع أي طلب مكرر والقائمة ممتلئة):
       perfumes → getAllPerfumes · incense → getAllIncenses ·
       ouds → getAllOuds
   ★ الصور من المنتج نفسه (Drive URL) — لا جلب إضافي.
   ============================================================ */

import { useEffect, useMemo } from "react";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_SORTS } from "../data/appConfig.js";
import { ATYAB_catalog } from "../data/products.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { catalogActions } from "../redux/slices/catalogSlice.js";
import {
  getAllPerfumes,
  selectPerfumesList,
  selectPerfumesStatus,
  selectPerfumesError
} from "../redux/slices/perfumesSlice.js";
import {
  getAllIncenses,
  selectIncensesList,
  selectIncensesStatus,
  selectIncensesError
} from "../redux/slices/incensesSlice.js";
import {
  getAllOuds,
  selectOudsList,
  selectOudsStatus,
  selectOudsError
} from "../redux/slices/oudsSlice.js";
/* ★ R23: شرائح «باقي المنتجات» — نفس الواجهة تمامًا */
import {
  getAllMists,
  selectMistsList,
  selectMistsStatus,
  selectMistsError
} from "../redux/slices/mistsSlice.js";
import {
  getAllLotions,
  selectLotionsList,
  selectLotionsStatus,
  selectLotionsError
} from "../redux/slices/lotionsSlice.js";
import {
  getAllMukhamaria,
  selectMukhamariaList,
  selectMukhamariaStatus,
  selectMukhamariaError
} from "../redux/slices/mukhamariaSlice.js";
import {
  getAllHair,
  selectHairList,
  selectHairStatus,
  selectHairError
} from "../redux/slices/hairSlice.js";

import { sortItems } from "../redux/selectors.js";
import { refreshCatalogStock } from "../redux/catalogStock.js";
import { atyabLog } from "../redux/api.js";
import { pluralAr, tr2 } from "../i18n.js";
import ProductCard from "../components/Product/ProductCard.jsx";
import { CardSkeleton } from "../components/Skeletons/index.js";
import UserRate from "../components/UserExperience/UserRate.jsx";
import { Icon } from "../components/Source/Icons.jsx";
import PromoNavButton from "../components/Buttons/PromoNavButton.jsx";
import { prevPromo } from "../constants/promoCycle.js";
import { toUserMessage } from "../api/friendlyError.js";

const SLICES = {
  perfumes: { thunk: getAllPerfumes, selectList: selectPerfumesList, selectStatus: selectPerfumesStatus, selectError: selectPerfumesError },
  incense: { thunk: getAllIncenses, selectList: selectIncensesList, selectStatus: selectIncensesStatus, selectError: selectIncensesError },
  ouds: { thunk: getAllOuds, selectList: selectOudsList, selectStatus: selectOudsStatus, selectError: selectOudsError },
  /* ★ R23: «باقي المنتجات» — نفس الواجهة، فيستوعبها CatalogPage مباشرة */
  mists: { thunk: getAllMists, selectList: selectMistsList, selectStatus: selectMistsStatus, selectError: selectMistsError },
  lotions: { thunk: getAllLotions, selectList: selectLotionsList, selectStatus: selectLotionsStatus, selectError: selectLotionsError },
  mukhamaria: { thunk: getAllMukhamaria, selectList: selectMukhamariaList, selectStatus: selectMukhamariaStatus, selectError: selectMukhamariaError },
  hair: { thunk: getAllHair, selectList: selectHairList, selectStatus: selectHairStatus, selectError: selectHairError }
};

function catalogKeyOf(value) {
  return value === "incense" || value === "ouds" || value === "mists" || value === "lotions" || value === "mukhamaria" || value === "hair" ? value : "perfumes";
}

export function CatalogPage(props) {
  const key = catalogKeyOf(props.catalogKey);
  const slice = SLICES[key];
  const dispatch = useAppDispatch();
  const catalog = ATYAB_catalog(key);

  /* الصفحة تُعلن نفسها (عنوان التبويب + data-route/data-catalog) */
  usePageMeta({
    route: key,
    catalog: key,
    titleAr: catalog.label,
    titleEn: catalog.labelEn
  });

  /* ★ الجلب من الـ API — يُنفَّذ فقط والقائمة فارغة (condition) */
  const status = useAppSelector(slice.selectStatus);
  const loadError = useAppSelector(slice.selectError);
  useEffect(
    function () {
      atyabLog("page catalog:mount", key);
      dispatch(slice.thunk());
      /* ★ تحديث المخزون الصامت (مخنوق 60ث): من دخل القائمة يرى
         الكميات الطازجة — بلا إعادة تحميل صور ولا وميض */
      refreshCatalogStock(dispatch);
    },
    [dispatch, slice, key]
  );

  const rawItems = useAppSelector(slice.selectList);

  const sort = useAppSelector(function (s) {
    return s.catalog.sort;
  });
  const active = useAppSelector(function (s) {
    return s.catalog.active;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  /* الكارت يستقبل المنتج مع mainImgUrl جاهزاً — الأولوية لصورة
     الـ API (ImageUrl)، وشريحة الصور تُكمل الناقص فقط.
     ★ الشبكة تعرض المتوفر فقط (الكمية > 0) — الصفر لا يُعرض،
     والحجز من العربة/التفاصيل. الخام يبقى في selectList. */
  const items = useMemo(
    function () {
      const visible = rawItems.filter(function (p) {
        return Number(p.stock) > 0;
      });
      return sortItems(visible, sort);
    },
    [rawItems, sort]
  );
  const count = items.length;
  /* ★ متوسط القسم من ratingAverage مرجّحاً بعدد المقيّمين — تُملأ به النجوم */
  const seed = useMemo(
    function () {
      let wsum = 0;
      let wtotal = 0;
      items.forEach(function (p) {
        const w = Number(p.reviews) || 0;
        const r = Number(p.rating) || 0;
        if (w > 0 && r > 0) { wsum += r * w; wtotal += w; }
      });
      return { avg: wtotal ? wsum / wtotal : 0, total: wtotal };
    },
    [items]
  );
  const loading = (status === "loading" || status === "idle") && count === 0;
  const failed = status === "failed" && count === 0;

  /* هذه الصفحة هي المعروضة الآن → تُعلن الكتالوج النشط */
  useEffect(
    function () {
      if (active !== key) dispatch(catalogActions.setActive(key));
    },
    [active, key, dispatch]
  );

  function retry() {
    dispatch(slice.thunk());
  }

  return (
    <>
      <div className="shop-bar">
        <div className="container">
          <div className="shop-bar-foot">
            <div className="sort">
              <label className="sr-only" htmlFor="sortSelect">
                ترتيب المنتجات
              </label>
              <select
                className="sort-select"
                id="sortSelect"
                value={sort}
                onChange={function (e) {
                  dispatch(catalogActions.setSort(e.target.value));
                }}
              >
                {(ATYAB_SORTS || []).map(function (option) {
                  return (
                    <option value={option.key} key={option.key}>
                      {language === "en" ? option.labelEn || option.label : option.label}
                    </option>
                  );
                })}
              </select>
            </div>

            <p className="result-line">
              <b>{count}</b>{" "}
              <span>
                {language === "en"
                  ? count === 1
                    ? catalog.nounFormsEn.one
                    : catalog.nounFormsEn.many
                  : pluralAr(count, catalog.nounForms)}
              </span>
            </p>
          </div>
        </div>
      </div>

      <section className="container view" id="listingView">
        {loading ? (
          <CardSkeleton count={8} />
        ) : failed ? (
          <div className="grid-empty grid-empty--error">
            <Icon name="info" strokeWidth={1.8} />
            <p>{toUserMessage(loadError, language) || "تعذّر الاتصال — تحقق من الإنترنت وحاول مجددًا."}</p>
            <button type="button" className="btn-primary" onClick={retry}>
              إعادة المحاولة
            </button>
          </div>
        ) : (
          <div className="grid">
            {items.map(function (p) {
              return <ProductCard product={p} key={p.id} />;
            })}
          </div>
        )}

        {!loading && !failed && count === 0 ? (
          <p className="grid-empty">
            <Icon name="info" strokeWidth={1.8} /> لا توجد منتجات في هذا
            التصنيف.
          </p>
        ) : null}

        {/* ★ R4: زر ذهبي للقسم السابق — بعد البطاقات وقبل التعليقات */}
        {!loading ? (
          <PromoNavButton page={prevPromo(key).page} label={prevPromo(key).label} labelEn={prevPromo(key).labelEn} />
        ) : null}

        <section className="reviews" id="reviewsSection">
          <div className="reviews-head">
            <span className="eyebrow">آراء العملاء</span>
            <h2>{catalog.reviewsTitle}</h2>
            <p className="reviews-sub">
              آراء حقيقية من عملاء أطياب الجاسم، ويمكنك إضافة تقييمك في الأسفل.
            </p>
          </div>
          <div className="reviews-box">
            <UserRate
              channelKey={catalog.reviewsChannel}
              display="marquee"
              seedAverage={seed.avg}
              seedTotal={seed.total}
              catalogKey={key}
              itemsCount={count}
              formTitle={tr2(
                language,
                "Your opinion matters",
                "رأيك يهمنا"
              )}
            />
          </div>
        </section>
      </section>
    </>
  );
}

export default function PerfumePage() {
  return <CatalogPage catalogKey="perfumes" />;
}
