/* ============================================================
   أطياب الجاسم (React) — زر التنقّل الذهبي بين الأقسام

   نفس شكل زر الهيدر الذهبي بالضبط (.atyab-gold-btn)، يُستعمل أسفل
   قوائم الأقسام (بعد البطاقات وقبل التعليقات) ويأخذ للقسم السابق
   في الدورة — سهمه معاكس لسهم الهيدر (→ للرجوع).
   ============================================================ */

import { Link } from "react-router-dom";
import { pathForPage } from "../../routes.js";
import { ATYAB_PAGES } from "../../data/appConfig.js";
import { useAppSelector } from "../../redux/hooks.js";
import { Icon } from "../Source/Icons.jsx";

export default function PromoNavButton(props) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const isEn = language === "en";
  return (
    <div className="promo-nav-wrap">
      <Link
        className="atyab-gold-btn"
        to={pathForPage(props.page, ATYAB_PAGES)}
        data-page={props.page}
        aria-label={isEn ? props.labelEn : props.label}
      >
        <span className="atyab-gold-spark" aria-hidden="true">
          <Icon name="spark" strokeWidth={2} />
        </span>
        <span>{isEn ? props.labelEn : props.label}</span>
        <span className="atyab-gold-arrow" aria-hidden="true">→</span>
      </Link>
    </div>
  );
}
