/* ============================================================
   أطياب الجاسم (React) — رسائل الخطأ بلغة العميل (friendlyError)

   القاعدة: لا يرى العميل أبدًا نصًا تقنيًا (رموز، أكواد، أسماء حقول،
   عناوين شبكة، أرقام حالات). كل ما يُعرض للمستخدم يمر من هنا:
     · نص الخادم العربي الواضح (detail/message) يُعرض كما هو.
     · النص التقني (استجابة الخادم: 503، تشغيل الـ API، رموز snake_case،
       أرقام الحالات، JSON/HTML/undefined...) يُستبدل برسالة مفهومة
       حسب السبب (انقطاع/مهلة/جلسة/تعارض/ضغط/عطل مؤقت).
     · كائنات الخطأ لا تُمس أبدًا (status/code/data تبقى للمنطق) —
       التصفية على النص المعروض فقط.

   خالصة بلا استيرادات حتى لا تُنشئ دورة اعتمادات.
   ============================================================ */

/* أنماط النص التقني الذي يجب ألا يراه العميل */
var TECHNICAL_RES = [
  /استجابة الخادم/,
  /غير صالحة من الخادم/,
  /تشغيل الـ?\s*API/,
  /على الخادم/,
  /الخادم رفض/,
  /\(رمز:/,
  /ENET[A-Z]*|ECONNABORTED|EABORTED|EEMPTYBODY|EREADBODY|EINVALIDJSON/,
  /\b[45]\d\d\b/,
  /:\s*\d{3}\b/,
  /undefined|null|NaN|\[object|Traceback/i,
  /\bJSON\b|\bHTML\b|\bError\s*:/,
  /\bfailed\b|\btimeout\b|\bnetwork\b|\babort\b/i,
  /https?:\/\//,
  /[A-Za-z]{2,}(?:_[A-Za-z0-9]+)+/
];

export function isTechnicalMessage(text) {
  const s = String(text == null ? "" : text);
  if (!s.trim()) return true;
  for (let i = 0; i < TECHNICAL_RES.length; i++) {
    if (TECHNICAL_RES[i].test(s)) return true;
  }
  return false;
}

function pickCandidate(err) {
  if (typeof err === "string") return err;
  if (err && typeof err === "object") {
    const d = (err.response && err.response.data) || {};
    if (d && typeof d === "object") {
      if (d.detail != null && String(d.detail).trim()) return String(d.detail);
      if (d.message != null && String(d.message).trim()) return String(d.message);
      if (d.title != null && String(d.title).trim()) return String(d.title);
      if (d.error != null && typeof d.error === "string" && d.error.trim()) return d.error;
    }
    if (typeof d === "string" && d.trim()) return d;
    if (err.message != null && String(err.message).trim()) return String(err.message);
  }
  return "";
}

function errCode(err) {
  return String((err && err.code) || "");
}

function errStatus(err) {
  const s = Number((err && err.status) || (err && err.response && err.response.status) || 0);
  return Number.isFinite(s) ? s : 0;
}

function isAbort(err) {
  return errCode(err) === "EABORTED" || (err && err.name === "AbortError");
}

/* رسائل بلغة العميل — [عربي، إنجليزي] */
var MSGS = {
  connection: ["تعذّر الاتصال — تحقق من الإنترنت ثم أعد المحاولة.", "Connection failed — check your internet and try again."],
  timeout: ["تأخّر الرد — تحقق من الاتصال ثم أعد المحاولة.", "The request timed out — check your connection and try again."],
  session: ["سجّل الدخول مجددًا للمزامنة ثم أعد المحاولة.", "Please log in again to sync, then try again."],
  notFound: ["لم نجد المطلوب — حدّث الصفحة وحاول مجددًا.", "We couldn't find that — refresh and try again."],
  conflict: ["تغيّرت البيانات أثناء عملك — نعرض الأحدث الآن، راجع وحاول مجددًا.", "The data changed while you were working — refresh and try again."],
  invalid: ["تحقق من البيانات المدخلة وحاول مجددًا.", "Please check the entered data and try again."],
  slowdown: ["طلبات كثيرة في وقت قصير — انتظر قليلًا ثم أعد المحاولة.", "Too many requests — wait a moment and try again."],
  temporary: ["عطل مؤقت في الخدمة — بياناتك محفوظة، حاول بعد قليل.", "Temporary service issue — your data is safe, try again shortly."],
  generic: ["حدث خطأ غير متوقع — حاول مجددًا، وإن تكرر راسلنا واتساب.", "Something went wrong — try again, or message us on WhatsApp if it persists."]
};

function msg(key, lang) {
  const pair = MSGS[key] || MSGS.generic;
  return lang === "en" ? pair[1] : pair[0];
}

/* المدخل الوحيد المعتمد لعرض أي خطأ للعميل */
export function toUserMessage(err, lang, fallback) {
  const en = lang === "en";
  const L = en ? "en" : "ar";
  if (isAbort(err)) return "";
  const candidate = pickCandidate(err);
  if (candidate && !isTechnicalMessage(candidate)) return candidate;
  const fb = String(fallback == null ? "" : fallback);
  if (fb && !isTechnicalMessage(fb)) return fb;
  const code = errCode(err);
  const st = errStatus(err);
  if (/TIMEOUT|ECONNABORTED/i.test(code)) return msg("timeout", L);
  if (st === 0 || /^ENET/i.test(code)) return msg("connection", L);
  if (st === 401 || st === 403) return msg("session", L);
  if (st === 404) return msg("notFound", L);
  if (st === 409) return msg("conflict", L);
  if (st === 422) return msg("invalid", L);
  if (st === 429) return msg("slowdown", L);
  if (st >= 500) return msg("temporary", L);
  return msg("generic", L);
}

export default toUserMessage;
