/* ============================================================
   أطياب الجاسم (React) — بطاقة المنتج (ProductCard)

   المكوّنات: مستطيل البطاقة + الصورة + شارة العرض في أعلى اليسار +
   العنوان + الشرح + السعر + السعر بعد الخصم + زر «أضف للعربة»،
   والقلب (AddToFavoritesButton)، والضغط على البطاقة يفتح
   ShowProductDetailsPage عبر مسار /product/<id>.

   ★ تُستعمل في صفحة العطور وصفحة البخور ونتائج البحث — الفرق بيانات.
   ★ extras (اختياري) تستعمله صفحة البحث: شارة النوع، سطر صغير تحت الاسم،
     ومقاطع الاسم/الشرح بعد تظليل أحرف البحث.
   ============================================================ */

import { memo } from "react";
import { Link } from "react-router-dom";
import { productPath } from "../../routes.js";
import { ATYAB_byId } from "../../data/products.js";
import { productName, productDesc, nounOf, tr2 } from "../../i18n.js";
import { useAppSelector } from "../../redux/hooks.js";
import { unitPriceOf } from "../../redux/selectors.js";
import { selectOfferMap } from "../../redux/slices/offersSlice.js";
import { Money } from "../Source/Money.jsx";
import { ProductImage } from "../Source/Icons.jsx";
import AddToFavoritesButton from "../Buttons/AddToFavoritesButton.jsx";
import { AddToCartButton } from "../Buttons/ProductButtons.jsx";

function Segments(props) {
  return (
    <>
      {(props.segments || []).map(function (seg, i) {
        return seg.hit ? (
          <mark className="sc-mark" key={i}>
            {seg.text}
          </mark>
        ) : (
          <span key={i}>{seg.text}</span>
        );
      })}
    </>
  );
}

function ProductCard(props) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  /* البطاقة تستقبل المنتج من الأب، وإن مُرّر id فقط نجلبه من البيانات */
  const p = props.product || (ATYAB_byId ? ATYAB_byId(Number(props.id)) : null);
  /* ★ كل الخطافات قبل أي return مبكر — قانون React */
  const offerMap = useAppSelector(selectOfferMap);
  if (!p) return null;

  const noun = nounOf(p, language);
  const name = productName(p, language);
  const desc = productDesc(p, language);
  const ex = props.extras || {};
  const now = unitPriceOf(p);
  const hasOffer = p.oldPrice && p.oldPrice > now;
  /* ★ منتج داخل عرض سارٍ؟ شارة «باقة» + عدّاد مصغّر لنهايته */
  const inOffer = offerMap[Number(p.id)] || null;
  const leftMs = inOffer && inOffer.expiresAt ? Math.max(0, Date.parse(inOffer.expiresAt) - Date.now()) : 0;
  const leftDays = Math.floor(leftMs / 86400e3);
  const leftHours = Math.floor((leftMs % 86400e3) / 3600e3);
  const leftText = !inOffer || !leftMs ? "" : leftDays > 0
    ? (language === "en" ? "Ends in " + leftDays + "d" : "ينتهي خلال " + leftDays + " " + (leftDays === 1 ? "يوم" : leftDays === 2 ? "يومين" : "أيام"))
    : (language === "en" ? "Ends in " + Math.max(1, leftHours) + "h" : "ينتهي خلال " + Math.max(1, leftHours) + " " + (leftHours <= 2 ? "ساعة" : "ساعات"));

  return (
    <article className="card" data-id={p.id}>
      <Link
        className="card-hit"
        to={productPath(p.id)}
        data-product={p.id}
        aria-label={tr2(language, "View details of " + name, "عرض تفاصيل " + noun + " " + name)}
      />
      <div className="card-media">
        <ProductImage product={p} alt={name} width="600" height="800" />
        {p.offer ? <span className="card-offer">{tr2(language, p.offerEn || p.offer, p.offer)}</span> : null}
        {inOffer ? <span className="card-bundle">{language === "en" ? "Bundle" : "باقة"}</span> : null}
        {ex.tag ? ex.tag : null}
        <AddToFavoritesButton id={p.id} name={name} />
      </div>
      <div className="card-body">
        <h3 className="card-name">{ex.nameSegments ? <Segments segments={ex.nameSegments} /> : name}</h3>
        {ex.meta ? <p className="card-meta">{ex.meta}</p> : null}
        <p className="card-desc">{ex.descSegments ? <Segments segments={ex.descSegments} /> : desc}</p>
        <div className="card-price">
          <span className="price-now">
            <Money sar={now} />
          </span>
          <span className="price-old">
            {hasOffer ? <Money sar={p.oldPrice} /> : null}
          </span>
        </div>
        {leftText ? (
          <p className="card-count">
            <span className="card-count-dot" aria-hidden="true" />
            {leftText}
          </p>
        ) : null}
        <AddToCartButton id={p.id} className="btn-cart" />
      </div>
    </article>
  );
}

export default memo(ProductCard);
